    std::cout << "Enter the word to count: ";
    std::cin >> wordToCount;
    inputFile.open("input_file.txt"); // Replace 'input_file.txt' with the actual filename

    // Read the file line-by-line and count word occurrences
    if (inputFile.is_open()) {
        std::string line;
        while (std::getline(inputFile, line)) {
            // Convert the line to lowercase for case-insensitive comparison
            std::transform(line.begin(), line.end(), line.begin(), ::tolower);

            size_t pos = 0;
            while ((pos = line.find(wordToCount, pos)) != std::string::npos) {
                ++wordCount;
                pos += wordToCount.length();
            }
        }
        inputFile.close();
    }
    else {
        std::cerr << "Error: Could not open input file." << std::endl;
        return -1; // Indicate error
    }

    std::cout << "The word " << wordToCount << " appears " << wordCount << " times in the file." << std::endl;

    return 0; // Program completed successfully
}
